@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@600&display=swap'); table, th, td, thead, :scope{ border: 3px double #805f00; font-size: 1.2rem; } table { width: 100%; text-align: center; border-collapse: collapse; font-family: 'Roboto'; background-color: #e0e1dd; } tr:nth-child(1), tr:nth-child(5), tr:nth-child(9), tr:nth-child(12) { background-color: #ffffff } .colspan3 { height: 50px; font-size: 1.3rem; color: #fff; font-weight: 400; } td { height: 40px; font-size: 1.3rem; } #date, #day { width: 45%; } #sno { height: 50px; width: 10%; } caption { font-size: 2rem; text-transform: uppercase } thead > tr:nth-child(1) { background-color: #805f00; text-transform: uppercase; color: #ffffff; font-size: 1.2rem; font-weight: 300; }
